  function sortShots() {
    shots.sort(function (a, b) {
      return Number(b.priority) - Number(a.priority);
    });
    save();
    render();
    showToast("Sorted by priority.");
  }

  function copyBrief() {
    var text = buildBrief();

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () {
        showToast("Brief copied.");
      }).catch(function () {
        fallbackCopy(text);
      });
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text) {
    var area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "readonly");
    area.style.position = "fixed";
    area.style.left = "-9999px";
    document.body.appendChild(area);
    area.select();

    try {
      document.execCommand("copy");
      showToast("Brief copied.");
    } catch (err) {
      showToast("Copy failed. Select the brief text manually.");
    }

    document.body.removeChild(area);
  }

  function downloadBrief() {
    var text = buildBrief();
    var blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    var date = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = "product-shot-production-brief-" + date + ".txt";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Brief downloaded.");
  }

  function clearShots() {
    shots = [];
    save();
    render();
    showToast("Shot list cleared.");
  }

  els.addShot.addEventListener("click", addShotFromForm);
  els.sampleShots.addEventListener("click", loadSample);
  els.clearShots.addEventListener("click", clearShots);
  els.sortShots.addEventListener("click", sortShots);
  els.copyBrief.addEventListener("click", copyBrief);
  els.downloadBrief.addEventListener("click", downloadBrief);

  load();
  render();
})();
